head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil70204";
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.fn_getSrtyData = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fn_getSrtyData = scwin.tx_fn_getSrtyData;
        scwin.init_fillGen();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil70204.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '3'); } }, { id: "btn_Register_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='3'); } }, { id: "btn_EtnSub", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "btn_Register_4", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='3'); } }, { id: "btn_EtnSub_2", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) >='4' && (dma_readDataVO.get("applStatusCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.applStatusCd"); })()) !== '03'); } }, { id: "btn_Register_3", fn: function(){ return ((dma_readDataVO.get("lastSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.lastSaveStatCd"); })()) < '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_356", entity: "dlt_readDataLpVO", countIds: [], cells: [{ childId: "한글회사명_2", fn: function (v, i) { return String(v("lpMbrNm")); } }, { childId: "영문회사명_2", fn: function (v, i) { return String(v("lpMbrEngNm")); } }, { childId: "본점소재지_2", fn: function (v, i) { return String(v("lpMbrAddr")); } }, { childId: "담당자_2", fn: function (v, i) { return String(v("lpChrgNm")); } }, { childId: "연락처_2", fn: function (v, i) { return String(v("lpChrgTelNo")); } }, { childId: "기준년월_8", fn: function (v, i) { return String(v("lpAcntclsYymm1")); } }, { childId: "기준년월_9", fn: function (v, i) { return String(v("lpAcntclsYymm2")); } }, { childId: "기준년월_10", fn: function (v, i) { return String(v("lpAcntclsYymm3")); } }, { childId: "영업용순자본", fn: function (v, i) { return String(v("lpFbzNetcap1")); } }, { childId: "영업용순자본_2", fn: function (v, i) { return String(v("lpFbzNetcap2")); } }, { childId: "영업용순자본_3", fn: function (v, i) { return String(v("lpFbzNetcap3")); } }, { childId: "총위험액", fn: function (v, i) { return String(v("lpTotRiskAmt1")); } }, { childId: "총위험액_2", fn: function (v, i) { return String(v("lpTotRiskAmt2")); } }, { childId: "총위험액_3", fn: function (v, i) { return String(v("lpTotRiskAmt3")); } }, { childId: "필요유지 자기자본", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal1")); } }, { childId: "필요유지 자기자본_2", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal2")); } }, { childId: "필요유지 자기자본_3", fn: function (v, i) { return String(v("lpReqPersisPrincCapVal3")); } }, { childId: "순자본비율", fn: function (v, i) { return String(v("lpNcr1")); } }, { childId: "순자본비율_2", fn: function (v, i) { return String(v("lpNcr2")); } }, { childId: "순자본비율_3", fn: function (v, i) { return String(v("lpNcr3")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    try {
        scwin.calIsuLimit();
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto1', 'etnSrtyPrincCapRto1'));
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto2', 'etnSrtyPrincCapRto2'));
        scwin.calRto($c.util.fieldEl('ipt_etnSrtyPrincCapRto3', 'etnSrtyPrincCapRto3'));
        scwin.insertComma(3);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil70204.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

