/**
 * @method
 * @name calRto
 * @description cal Rto 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.calRto = function (obj) {
    const nm = obj.name;
    const no = nm.substr(nm.length - 1, 1);
    form = (document.etnListForm || { elements: [] });
    if (no === '1') {
        if ($c.util.getComponent('ipt_riskAsstVal1').getValue()=== 0 || ($c.util.getComponent('ipt_riskAsstVal1').getValue() == null ? '' : String($c.util.getComponent('ipt_riskAsstVal1').getValue())) === '') {
            $c.util.getComponent("ipt_etnSrtyPrincCapRto1").setValue('');
        } else {
            $c.util.getComponent("ipt_etnSrtyPrincCapRto1").setValue(Math.floor(($c.util.getComponent('ipt_basEqtycap1').getValue()* 100 / $c.util.getComponent('ipt_riskAsstVal1').getValue()) * 100) / 100);
        }
    } else {
        if (no === '2') {
            if ($c.util.getComponent('ipt_riskAsstVal2').getValue()=== 0 || ($c.util.getComponent('ipt_riskAsstVal2').getValue() == null ? '' : String($c.util.getComponent('ipt_riskAsstVal2').getValue())) === '') {
                $c.util.getComponent("ipt_etnSrtyPrincCapRto2").setValue('');
            } else {
                $c.util.getComponent("ipt_etnSrtyPrincCapRto2").setValue(Math.floor(($c.util.getComponent('ipt_basEqtycap2').getValue()* 100 / $c.util.getComponent('ipt_riskAsstVal2').getValue()) * 100) / 100);
            }
        } else {
            if (no === '3') {
                if ($c.util.getComponent('ipt_riskAsstVal3').getValue()=== 0 || ($c.util.getComponent('ipt_riskAsstVal3').getValue() == null ? '' : String($c.util.getComponent('ipt_riskAsstVal3').getValue())) === '') {
                    $c.util.getComponent("ipt_etnSrtyPrincCapRto3").setValue('');
                } else {
                    $c.util.getComponent("ipt_etnSrtyPrincCapRto3").setValue(Math.floor(($c.util.getComponent('ipt_basEqtycap3').getValue()* 100 / $c.util.getComponent('ipt_riskAsstVal3').getValue()) * 100) / 100);
                }
            }
        }
    }
};

/**
 * @method
 * @name calIsuLimit
 * @description cal Isu Limit 처리
 * @returns {void}
 * @hidden N
 */
scwin.calIsuLimit = function () {
    form = (document.etnListForm || { elements: [] });
    if ($c.util.getComponent('ipt_srtyEqtycap').getValue()=== 0 || ($c.util.getComponent('ipt_srtyEqtycap').getValue() == null ? '' : String($c.util.getComponent('ipt_srtyEqtycap').getValue())) === '') {
        $c.util.getComponent("ipt_srtyIsuLimit").setValue('');
    } else {
        $c.util.getComponent("ipt_srtyIsuLimit").setValue(Math.floor(((parseInt($c.util.getComponent('ipt_srtyIsuTotamt').getValue()) + parseInt($c.util.getComponent('ipt_srtyMiscIsuAmt').getValue())) / $c.util.getComponent('ipt_srtyEqtycap').getValue()) * 100 * 100) / 100);
    }
};

/**
 * @method
 * @name removeComma
 * @description remove Comma 처리
 * @param {*} tab tab
 * @returns {void}
 * @hidden N
 */
scwin.removeComma = function (tab) {

    form = (document.etnListForm || { elements: [] });
    const elem = $c.util.getComponent('etnListForm').elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('etnIsuQty') >= 0 ||
                elem[i].name.indexOf('isuOrgnVal') >= 0 ||
                // elem[i].name.indexOf('traceYdMult') >= 0 ||
                elem[i].name.indexOf('lpHdQty') >= 0 ||
                elem[i].name.indexOf('declSpd') >= 0 ||
                elem[i].name.indexOf('halfwyRedmptUnit') >= 0 ||
                elem[i].name.indexOf('etnIsuPrc') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('fbzNetcap') >= 0 ||
                elem[i].name.indexOf('totRiskAmt') >= 0 ||
                elem[i].name.indexOf('reqPersisPrincCapVal') >= 0 ||
                (elem[i].name.indexOf('ncr') >= 0 && elem[i].name.indexOf('ncrAcntclsYymm') < 0) ||
                elem[i].name.indexOf('eqtycap') >= 0 ||
                elem[i].name.indexOf('isuTotamt') >= 0 ||
                elem[i].name.indexOf('isuLimit') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    } else if(tab === 3) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueResetRmComma2(elem[i]);
        }
    }
};

